struct AssetRequest
{
    AssetID Asset;
    ResidencyPriority Priority;
};

enum class ResidencyState
{
    Unloaded,
    Loading,
    CPUResident,
    Uploading,
    GPUResident,
    EvictPending,
    Failed
};

struct AssetRuntimeEntry
{
    AssetID Asset;
    ResidencyState State;

    std::size_t CPUBytes;
    std::size_t GPUBytes;

    std::uint64_t LastUsedFrame;
    std::uint32_t PinCount;
};

struct TextureEntry
{
    AssetID Asset;

    std::uint64_t Revision;

    TextureRuntimeHandle Current;
};

void PublishReplacement(
    TextureEntry& entry,
    TextureRuntimeHandle replacement)
{
    TextureRuntimeHandle old =
        entry.Current;

    entry.Current = replacement;
    ++entry.Revision;

    RetireAfterGPUCompletion(old);
}

