Chapter.Code:
struct Camera
{
    ProjectionMode Mode;
    float VerticalFov;
    float NearPlane;
    float FarPlane;
};

struct FileHeader
{
    std::uint32_t Magic;
    std::uint32_t Version;
};

CameraV2 Migrate(
    const CameraV1& old)
{
    CameraV2 result;

    result.VerticalFov =
        ConvertHorizontalToVertical(
            old.HorizontalFov,
            old.AssumedAspectRatio);

    result.NearPlane =
        old.NearPlane;

    return result;
}

void WriteU32LE(
    Writer& out,
    std::uint32_t value)
{
    std::byte bytes[4]
    {
        std::byte(value & 0xff),
        std::byte((value >> 8) & 0xff),
        std::byte((value >> 16) & 0xff),
        std::byte((value >> 24) & 0xff)
    };

    out.Write(bytes);
}

Scene candidate;

ParseInto(candidate);
Validate(candidate);

liveScene =
    std::move(candidate);

TypeDescriptor CameraDescriptor()
{
    TypeDescriptor type;

    type.Key =
        "Kairo.Engine.Camera";

    type.DisplayName =
        "Camera";

    type.Properties.push_back(
        MakeMemberProperty<Camera>(
            {
                .Key =
                    "near-plane",
                .DisplayName =
                    "Near Plane"
            },
            &Camera::NearPlane));

    return type;
}

descriptor.Read =
    [member](const void* object)
    {
        const Object* typed =
            static_cast<
                const Object*>(
                    object);

        return Encode(
            typed->*member);
    };

descriptor.Write =
    [member](
        void* object,
        const PropertyValue& value)
    {
        Object* typed =
            static_cast<Object*>(
                object);

        typed->*member =
            Decode<Member>(value);
    };

template<>
struct Reflection<Camera>
{
    static constexpr auto Key =
        "Kairo.Engine.Camera";

    static TypeDescriptor Build();
};

void Camera::SetNear(float n)
{
    if (n <= 0)
        throw ...;

    NearPlane = n;
}

for (const auto& property
     : descriptor.Properties)
{
    PropertyValue value =
        registry.Read(
            typeKey,
            property.Key,
            object);

    writer.Write(
        property.Key,
        value);
}

for (SerializedField field : input)
{
    const PropertyDescriptor* p =
        descriptor.Find(field.ID);

    if (!p)
    {
        HandleUnknown(field);
        continue;
    }

    PropertyValue value =
        Decode(
            field,
            p->ValueKind);

    registry.Write(
        descriptor.Key,
        p->Key,
        object,
        value);
}

struct ReflectedObjectView
{
    void* Object = nullptr;
    const TypeDescriptor* Type = nullptr;
};

PropertyValue Read(
    ReflectedObjectView object,
    PropertyID property);

struct ErasedObject
{
    void* Data;
    TypeID Type;
};
